329→
330→    // Spawn assistant in background
331→    try {
332→      log.info("Spawning assistant session...");
333→      const { session, ready } = await spawnAssistant(
334→        this.core as OpenACPCore,
335→        this,
336→        this.assistantTopicId,
337→      );
338→      this.assistantSession = session;
339→      this.assistantInitializing = true;
340→      log.info({ sessionId: session.id }, "Assistant session ready, system prompt running in background");
341→      ready.then(() => {
342→        this.assistantInitializing = false;
343→        log.info({ sessionId: session.id }, "Assistant ready for user messages");
344→      });
345→    } catch (err) {
346→      log.error({ err }, "Failed to spawn assistant");
347→      this.bot.api.sendMessage(
348→        this.telegramConfig.chatId,
349→        `⚠️ <b>Failed to start assistant session.</b>\n\n<code>${err instanceof Error ? err.message : String(err)}</code>`,
350→        { message_thread_id: this.assistantTopicId, parse_mode: "HTML" },
351→      ).catch(() => {});
352→    }
353→  }
354→
355→  async stop(): Promise<void> {
356→    if (this.assistantSession) {
357→      await this.assistantSession.destroy();
358→    }
359→    await this.bot.stop();
360→    log.info("Telegram bot stopped");
