147→// ─── PlanCard ─────────────────────────────────────────────────────────────────
148→
149→function formatPlanCard(entries: PlanEntry[]): string {
150→  const statusIcon: Record<string, string> = {
151→    completed: '✅',
152→    in_progress: '🔄',
153→    pending: '⬜',
154→    failed: '❌',
155→  }
156→  const total = entries.length
157→  const done = entries.filter(e => e.status === 'completed').length
158→  const ratio = total > 0 ? done / total : 0
159→  const filled = Math.round(ratio * 10)
160→  const bar = '▓'.repeat(filled) + '░'.repeat(10 - filled)
161→  const pct = Math.round(ratio * 100)
162→  const header = `📋 <b>Plan</b>\n${bar} ${pct}% · ${done}/${total}`
163→  const lines = entries.map((e, i) => {
164→    const icon = statusIcon[e.status] ?? '⬜'
165→    return `${icon} ${i + 1}. ${e.content}`
166→  })
167→  return [header, ...lines].join('\n')
168→}
169→
170→export class PlanCard {
171→  private msgId?: number
172→  private flushPromise: Promise<void> = Promise.resolve()
173→  private latestEntries?: PlanEntry[]
174→  private lastSentText?: string
175→  private flushTimer?: ReturnType<typeof setTimeout>
176→
177→  constructor(
178→    private api: Bot['api'],
179→    private chatId: number,
180→    private threadId: number,
181→    private sendQueue: TelegramSendQueue,
182→  ) {}
183→
184→  update(entries: PlanEntry[]): void {
185→    this.latestEntries = entries
186→    if (this.flushTimer) clearTimeout(this.flushTimer)
187→    this.flushTimer = setTimeout(() => {
188→      this.flushTimer = undefined
189→      this.flushPromise = this.flushPromise
190→        .then(() => this._flush())
191→        .catch(() => {})
192→    }, 3500)
193→  }
194→
195→  async finalize(): Promise<void> {
196→    if (!this.latestEntries) return
197→    if (this.flushTimer) {
198→      clearTimeout(this.flushTimer)
199→      this.flushTimer = undefined
200→    }
201→    await this.flushPromise
202→    this.flushPromise = this.flushPromise
203→      .then(() => this._flush())
204→      .catch(() => {})
205→    await this.flushPromise
206→  }
207→
208→  destroy(): void {
209→    if (this.flushTimer) {
210→      clearTimeout(this.flushTimer)
211→      this.flushTimer = undefined
212→    }
213→  }
214→
215→  private async _flush(): Promise<void> {
216→    if (!this.latestEntries) return
217→    const text = formatPlanCard(this.latestEntries)
218→    if (this.msgId && text === this.lastSentText) return
219→    this.lastSentText = text
220→    try {
221→      if (this.msgId) {
222→        await this.sendQueue.enqueue(() =>
223→          this.api.editMessageText(this.chatId, this.msgId!, text, {
224→            parse_mode: 'HTML',
225→          }),
226→        )
227→      } else {
228→        const result = await this.sendQueue.enqueue(() =>
229→          this.api.sendMessage(this.chatId, text, {
230→            message_thread_id: this.threadId,
231→            parse_mode: 'HTML',
232→            disable_notification: true,
233→          }),
234→        )
235→        if (result) this.msgId = result.message_id
236→      }
237→    } catch (err) {
238→      log.warn({ err }, 'PlanCard flush failed')
239→    }
240→  }
241→}
242→
243→// ─── ActivityTracker ──────────────────────────────────────────────────────────
244→
245→export class ActivityTracker {
246→  private isFirstEvent = true
247→  private hasPlanCard = false
248→  private thinking: ThinkingIndicator
249→  private planCard: PlanCard
250→  private usage: UsageMessage
251→
252→  constructor(
253→    private api: Bot['api'],
254→    private chatId: number,
255→    private threadId: number,
256→    private sendQueue: TelegramSendQueue,
257→  ) {
258→    this.thinking = new ThinkingIndicator(api, chatId, threadId, sendQueue)
259→    this.planCard = new PlanCard(api, chatId, threadId, sendQueue)
260→    this.usage = new UsageMessage(api, chatId, threadId, sendQueue)
261→  }
262→
263→  async onNewPrompt(): Promise<void> {
264→    this.isFirstEvent = true
265→    this.hasPlanCard = false
266→    this.thinking.dismiss()
267→    this.thinking.reset()
268→  }
269→
270→  async onThought(): Promise<void> {
271→    await this._firstEventGuard()
272→    await this.thinking.show()
273→  }
274→
275→  async onPlan(entries: PlanEntry[]): Promise<void> {
276→    await this._firstEventGuard()
277→    this.thinking.dismiss()
278→    this.hasPlanCard = true
279→    this.planCard.update(entries)
280→  }
281→
282→  async onToolCall(): Promise<void> {
283→    await this._firstEventGuard()
284→    this.thinking.dismiss()
285→    this.thinking.reset()
286→  }
287→
288→  async onTextStart(): Promise<void> {
289→    await this._firstEventGuard()
290→    this.thinking.dismiss()
291→  }
292→
293→  async sendUsage(data: { tokensUsed?: number; contextSize?: number }): Promise<void> {
294→    await this.usage.send(data)
295→  }
296→
297→  getUsageMsgId(): number | undefined {
298→    return this.usage.getMsgId()
299→  }
300→
301→  async onComplete(): Promise<void> {
302→    if (this.hasPlanCard) {
303→      await this.planCard.finalize()
304→    } else {
305→      try {
306→        await this.sendQueue.enqueue(() =>
307→          this.api.sendMessage(this.chatId, '✅ <b>Done</b>', {
308→            message_thread_id: this.threadId,
309→            parse_mode: 'HTML',
310→            disable_notification: true,
311→          }),
312→        )
313→      } catch (err) {
314→        log.warn({ err }, 'ActivityTracker.onComplete() Done send failed')
315→      }
316→    }
317→  }
318→
319→  destroy(): void {
320→    this.thinking.dismiss()
321→    this.planCard.destroy()
322→  }
323→
324→  private async _firstEventGuard(): Promise<void> {
325→    if (!this.isFirstEvent) return
326→    this.isFirstEvent = false
327→    await this.usage.delete()
328→  }
329→}
