 39→export function setupAllCallbacks(
 40→  bot: Bot,
 41→  core: OpenACPCore,
 42→  chatId: number,
 43→  systemTopicIds?: { notificationTopicId: number; assistantTopicId: number },
 44→  getAssistantSession?: () => { topicId: number; enqueuePrompt: (p: string) => Promise<void> } | undefined,
 45→): void {
 46→  // Register specific prefix handlers FIRST (grammY middleware order matters)
 47→  setupNewSessionCallbacks(bot, core, chatId);
 48→  setupSessionCallbacks(bot, core, chatId, systemTopicIds);
 49→
 50→  // Settings handlers — must be before broad m: handler
 51→  setupSettingsCallbacks(bot, core, getAssistantSession ?? (() => undefined))
 52→
 53→  // Doctor handlers — must be before broad m: handler
 54→  setupDoctorCallbacks(bot);
 55→
 56→  // Agent callbacks (install + pagination) — must be before broad m: handler
 57→  bot.callbackQuery(/^ag:/, (ctx) => handleAgentCallback(ctx, core));
 58→
 59→  // New session with specific agent callback — must be before broad m: handler
 60→  bot.callbackQuery(/^na:/, async (ctx) => {
 61→    const agentKey = ctx.callbackQuery.data!.replace("na:", "");
 62→    await ctx.answerCallbackQuery();
 63→    await createSessionDirect(ctx, core, chatId, agentKey, core.configManager.get().workspace.baseDir);
 64→  });
 65→
 66→  // Broad m: handler for remaining menu dispatch — LAST
 67→  bot.callbackQuery(/^m:/, async (ctx) => {
 68→    const data = ctx.callbackQuery.data;
 69→    try {
 70→      await ctx.answerCallbackQuery();
 71→    } catch { /* expired or network — ignore */ }
 72→
 73→    switch (data) {
 74→      case "m:new":
 75→        await handleNew(ctx, core, chatId);
 76→        break;
 77→      case "m:status":
 78→        await handleStatus(ctx, core);
 79→        break;
 80→      case "m:agents":
 81→        await handleAgents(ctx, core);
 82→        break;
 83→      case "m:help":
 84→        await handleHelp(ctx);
 85→        break;
 86→      case "m:restart":
 87→        await handleRestart(ctx, core);
 88→        break;
 89→      case "m:update":
 90→        await handleUpdate(ctx, core);
 91→        break;
 92→      case "m:integrate":
 93→        await handleIntegrate(ctx, core);
 94→        break;
 95→      case "m:topics":
 96→        await handleTopics(ctx, core);
 97→        break;
 98→      case "m:settings":
 99→        await handleSettings(ctx, core);
100→        break;
101→    }
102→  });
103→}
