 63→export async function handleEnableDangerous(ctx: Context, core: OpenACPCore): Promise<void> {
 64→  const threadId = ctx.message?.message_thread_id;
 65→  if (!threadId) {
 66→    await ctx.reply("⚠️ This command only works inside a session topic.", { parse_mode: "HTML" });
 67→    return;
 68→  }
 69→  const session = core.sessionManager.getSessionByThread("telegram", String(threadId));
 70→  if (session) {
 71→    if (session.dangerousMode) {
 72→      await ctx.reply("☠️ Dangerous mode is already enabled.", { parse_mode: "HTML" });
 73→      return;
 74→    }
 75→    session.dangerousMode = true;
 76→    core.sessionManager.patchRecord(session.id, { dangerousMode: true }).catch(() => {});
 77→  } else {
 78→    // Session not in memory (e.g. after restart) — update store directly
 79→    const record = core.sessionManager.getRecordByThread("telegram", String(threadId));
 80→    if (!record || record.status === "cancelled" || record.status === "error") {
 81→      await ctx.reply("⚠️ No active session in this topic.", { parse_mode: "HTML" });
 82→      return;
 83→    }
 84→    if (record.dangerousMode) {
 85→      await ctx.reply("☠️ Dangerous mode is already enabled.", { parse_mode: "HTML" });
 86→      return;
 87→    }
 88→    core.sessionManager.patchRecord(record.sessionId, { dangerousMode: true }).catch(() => {});
 89→  }
 90→  await ctx.reply(
 91→    `⚠️ <b>Dangerous mode enabled</b>\n\nAll permission requests will be auto-approved. Claude can run arbitrary commands without asking.\n\nUse /disable_dangerous to restore normal behaviour.`,
 92→    { parse_mode: "HTML" },
 93→  );
 94→}
