  7→const AGENTS_PER_PAGE = 6;
  8→
  9→export async function handleAgents(ctx: Context, core: OpenACPCore, page = 0): Promise<void> {
 10→  const catalog = core.agentCatalog;
 11→  const items = catalog.getAvailable();
 12→
 13→  const installed = items.filter((i) => i.installed);
 14→  const available = items.filter((i) => !i.installed);
 15→
 16→  let text = "<b>🤖 Agents</b>\n\n";
 17→
 18→  // Installed agents section
 19→  if (installed.length > 0) {
 20→    text += "<b>Installed:</b>\n";
 21→    for (const item of installed) {
 22→      text += `✅ <b>${escapeHtml(item.name)}</b>`;
 23→      if (item.description) {
 24→        text += ` — <i>${escapeHtml(truncate(item.description, 50))}</i>`;
 25→      }
 26→      text += "\n";
 27→    }
 28→    text += "\n";
 29→  }
 30→
 31→  // Available agents section (paginated)
 32→  if (available.length > 0) {
 33→    const totalPages = Math.ceil(available.length / AGENTS_PER_PAGE);
 34→    const safePage = Math.max(0, Math.min(page, totalPages - 1));
 35→    const pageItems = available.slice(safePage * AGENTS_PER_PAGE, (safePage + 1) * AGENTS_PER_PAGE);
 36→
 37→    text += `<b>Available to install:</b>`;
 38→    if (totalPages > 1) {
 39→      text += ` (${safePage + 1}/${totalPages})`;
 40→    }
 41→    text += "\n";
 42→
 43→    for (const item of pageItems) {
 44→      if (item.available) {
 45→        text += `⬇️ <b>${escapeHtml(item.name)}</b>`;
 46→      } else {
 47→        const deps = item.missingDeps?.join(", ") ?? "requirements not met";
 48→        text += `⚠️ <b>${escapeHtml(item.name)}</b> <i>(needs: ${escapeHtml(deps)})</i>`;
 49→      }
 50→      if (item.description) {
 51→        text += `\n    <i>${escapeHtml(truncate(item.description, 60))}</i>`;
 52→      }
 53→      text += "\n";
 54→    }
 55→
 56→    // Install buttons for current page
 57→    const keyboard = new InlineKeyboard();
 58→    const installable = pageItems.filter((i) => i.available);
 59→    for (let i = 0; i < installable.length; i += 2) {
 60→      const row = installable.slice(i, i + 2);
 61→      for (const item of row) {
 62→        keyboard.text(`⬇️ ${item.name}`, `ag:install:${item.key}`);
 63→      }
 64→      keyboard.row();
 65→    }
 66→
 67→    // Pagination buttons
 68→    if (totalPages > 1) {
 69→      if (safePage > 0) {
 70→        keyboard.text("◀️ Prev", `ag:page:${safePage - 1}`);
 71→      }
 72→      if (safePage < totalPages - 1) {
 73→        keyboard.text("Next ▶️", `ag:page:${safePage + 1}`);
 74→      }
 75→      keyboard.row();
 76→    }
 77→
 78→    // Tip for CLI install
 79→    if (available.some((i) => !i.available)) {
 80→      text += "\n💡 <i>Agents marked ⚠️ need additional setup. Use</i> <code>openacp agents info &lt;name&gt;</code> <i>for details.</i>\n";
 81→    }
 82→
 83→    await ctx.reply(text, { parse_mode: "HTML", reply_markup: keyboard });
 84→  } else {
 85→    text += "<i>All agents are already installed!</i>";
 86→    await ctx.reply(text, { parse_mode: "HTML" });
 87→  }
 88→}
