 95→  if (!nameOrId) {
 96→    await ctx.reply(
 97→      "📦 <b>Install an agent</b>\n\n" +
 98→        "Usage: <code>/install &lt;agent-name&gt;</code>\n" +
 99→        "Example: <code>/install gemini</code>\n\n" +
