109→export async function handleAgentCallback(ctx: Context, core: OpenACPCore): Promise<void> {
110→  const data = ctx.callbackQuery?.data ?? "";
111→  await ctx.answerCallbackQuery();
112→
113→  if (data.startsWith("ag:install:")) {
114→    const nameOrId = data.replace("ag:install:", "");
115→    await installAgentWithProgress(ctx, core, nameOrId);
116→    return;
117→  }
118→
119→  if (data.startsWith("ag:page:")) {
120→    const page = parseInt(data.replace("ag:page:", ""), 10);
121→    // Edit the existing message with the new page
122→    try {
123→      const catalog = core.agentCatalog;
124→      const items = catalog.getAvailable();
125→      const installed = items.filter((i) => i.installed);
126→      const available = items.filter((i) => !i.installed);
127→
128→      let text = "<b>🤖 Agents</b>\n\n";
129→
130→      if (installed.length > 0) {
131→        text += "<b>Installed:</b>\n";
132→        for (const item of installed) {
133→          text += `✅ <b>${escapeHtml(item.name)}</b>`;
134→          if (item.description) {
135→            text += ` — <i>${escapeHtml(truncate(item.description, 50))}</i>`;
136→          }
137→          text += "\n";
138→        }
139→        text += "\n";
140→      }
141→
142→      const totalPages = Math.ceil(available.length / AGENTS_PER_PAGE);
143→      const safePage = Math.max(0, Math.min(page, totalPages - 1));
144→      const pageItems = available.slice(safePage * AGENTS_PER_PAGE, (safePage + 1) * AGENTS_PER_PAGE);
145→
146→      text += `<b>Available to install:</b>`;
147→      if (totalPages > 1) {
148→        text += ` (${safePage + 1}/${totalPages})`;
149→      }
150→      text += "\n";
151→
152→      for (const item of pageItems) {
153→        if (item.available) {
154→          text += `⬇️ <b>${escapeHtml(item.name)}</b>`;
155→        } else {
156→          const deps = item.missingDeps?.join(", ") ?? "requirements not met";
157→          text += `⚠️ <b>${escapeHtml(item.name)}</b> <i>(needs: ${escapeHtml(deps)})</i>`;
158→        }
159→        if (item.description) {
160→          text += `\n    <i>${escapeHtml(truncate(item.description, 60))}</i>`;
161→        }
162→        text += "\n";
163→      }
164→
165→      const keyboard = new InlineKeyboard();
166→      const installable = pageItems.filter((i) => i.available);
167→      for (let i = 0; i < installable.length; i += 2) {
168→        const row = installable.slice(i, i + 2);
169→        for (const item of row) {
170→          keyboard.text(`⬇️ ${item.name}`, `ag:install:${item.key}`);
171→        }
172→        keyboard.row();
173→      }
174→
175→      if (totalPages > 1) {
176→        if (safePage > 0) {
177→          keyboard.text("◀️ Prev", `ag:page:${safePage - 1}`);
178→        }
179→        if (safePage < totalPages - 1) {
180→          keyboard.text("Next ▶️", `ag:page:${safePage + 1}`);
181→        }
182→        keyboard.row();
183→      }
184→
185→      await ctx.editMessageText(text, { parse_mode: "HTML", reply_markup: keyboard });
186→    } catch { /* ignore edit failures */ }
187→  }
188→}
