  9→const pendingFixesStore = new Map<string, PendingFix[]>();
 10→
 11→function renderReport(report: DoctorReport): { text: string; keyboard: InlineKeyboard | undefined } {
 12→  const icons = { pass: "✅", warn: "⚠️", fail: "❌" };
 13→  const lines: string[] = ["🩺 <b>OpenACP Doctor</b>\n"];
 14→
 15→  for (const category of report.categories) {
 16→    lines.push(`<b>${category.name}</b>`);
 17→    for (const result of category.results) {
 18→      lines.push(`  ${icons[result.status]} ${escapeHtml(result.message)}`);
 19→    }
 20→    lines.push("");
 21→  }
 22→
 23→  const { passed, warnings, failed, fixed } = report.summary;
 24→  const fixedStr = fixed > 0 ? `, ${fixed} fixed` : "";
 25→  lines.push(`<b>Result:</b> ${passed} passed, ${warnings} warnings, ${failed} failed${fixedStr}`);
 26→
 27→  let keyboard: InlineKeyboard | undefined;
 28→  if (report.pendingFixes.length > 0) {
 29→    keyboard = new InlineKeyboard();
 30→    for (let i = 0; i < report.pendingFixes.length; i++) {
 31→      const label = `🔧 Fix: ${report.pendingFixes[i].message.slice(0, 30)}`;
 32→      keyboard.text(label, `m:doctor:fix:${i}`).row();
 33→    }
 34→  }
 35→
 36→  return { text: lines.join("\n"), keyboard };
 37→}
 38→
 39→function escapeHtml(text: string): string {
 40→  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
 41→}
