 43→export async function handleDoctor(ctx: Context): Promise<void> {
 44→  const statusMsg = await ctx.reply("🩺 Running diagnostics...", { parse_mode: "HTML" });
 45→
 46→  try {
 47→    const engine = new DoctorEngine();
 48→    const report = await engine.runAll();
 49→    const { text, keyboard } = renderReport(report);
 50→
 51→    const storeKey = `${ctx.chat!.id}:${statusMsg.message_id}`;
 52→    if (report.pendingFixes.length > 0) {
 53→      pendingFixesStore.set(storeKey, report.pendingFixes);
 54→    }
 55→
 56→    await ctx.api.editMessageText(ctx.chat!.id, statusMsg.message_id, text, {
 57→      parse_mode: "HTML",
 58→      reply_markup: keyboard,
 59→    });
 60→  } catch (err) {
 61→    log.error({ err }, "Doctor command failed");
 62→    await ctx.api.editMessageText(
 63→      ctx.chat!.id,
 64→      statusMsg.message_id,
 65→      `❌ Doctor failed: ${err instanceof Error ? err.message : String(err)}`,
 66→      { parse_mode: "HTML" },
 67→    );
 68→  }
 69→}
