 71→export function setupDoctorCallbacks(bot: Bot): void {
 72→  bot.callbackQuery(/^m:doctor:fix:/, async (ctx) => {
 73→    const data = ctx.callbackQuery.data;
 74→    const index = parseInt(data.replace("m:doctor:fix:", ""), 10);
 75→    const chatId = ctx.callbackQuery.message?.chat.id;
 76→    const messageId = ctx.callbackQuery.message?.message_id;
 77→
 78→    try {
 79→      await ctx.answerCallbackQuery({ text: "Applying fix..." });
 80→    } catch { /* expired */ }
 81→
 82→    if (chatId === undefined || messageId === undefined) return;
 83→
 84→    const storeKey = `${chatId}:${messageId}`;
 85→    const fixes = pendingFixesStore.get(storeKey);
 86→    if (!fixes || index < 0 || index >= fixes.length) {
 87→      try { await ctx.answerCallbackQuery({ text: "Fix no longer available" }); } catch { /* */ }
 88→      return;
 89→    }
 90→
 91→    const pending = fixes[index];
 92→    try {
 93→      const result = await pending.fix();
 94→      if (result.success) {
 95→        const engine = new DoctorEngine();
 96→        const report = await engine.runAll();
 97→        const { text, keyboard } = renderReport(report);
 98→
 99→        if (report.pendingFixes.length > 0) {
100→          pendingFixesStore.set(storeKey, report.pendingFixes);
101→        } else {
102→          pendingFixesStore.delete(storeKey);
103→        }
104→
105→        await ctx.editMessageText(text, { parse_mode: "HTML", reply_markup: keyboard });
106→      } else {
107→        try { await ctx.answerCallbackQuery({ text: `Fix failed: ${result.message}` }); } catch { /* */ }
108→      }
109→    } catch (err) {
110→      log.error({ err, index }, "Doctor fix callback failed");
111→    }
112→  });
113→
114→  bot.callbackQuery("m:doctor", async (ctx) => {
115→    try { await ctx.answerCallbackQuery(); } catch { /* */ }
116→    await handleDoctor(ctx);
117→  });
118→}
