 34→export function setupIntegrateCallbacks(
 35→  bot: Bot,
 36→  core: OpenACPCore,
 37→): void {
 38→  bot.callbackQuery(/^i:/, async (ctx) => {
 39→    const data = ctx.callbackQuery.data;
 40→    try {
 41→      await ctx.answerCallbackQuery();
 42→    } catch {
 43→      /* expired */
 44→    }
 45→
 46→    // Back to agent list
 47→    if (data === "i:back") {
 48→      const { listIntegrations } = await import("../../../cli/integrate.js");
 49→      const agents = listIntegrations();
 50→      const keyboard = new InlineKeyboard();
 51→      for (const agent of agents) {
