 53→      }
 54→      try {
 55→        await ctx.editMessageText(
 56→          `<b>🔗 Integrations</b>\n\nSelect an agent to manage its integrations.`,
 57→          { parse_mode: "HTML", reply_markup: keyboard },
 58→        );
 59→      } catch { /* message unchanged */ }
 60→      return;
 61→    }
 62→
 63→    // Show agent items
 64→    const agentMatch = data.match(/^i:agent:(.+)$/);
 65→    if (agentMatch) {
 66→      const agentName = agentMatch[1];
 67→      const { getIntegration } = await import("../../../cli/integrate.js");
 68→      const integration = getIntegration(agentName);
 69→      if (!integration) {
 70→        await ctx.reply(`❌ No integration available for '${escapeHtml(agentName)}'.`, { parse_mode: "HTML" });
 71→        return;
 72→      }
 73→      const keyboard = buildAgentItemsKeyboard(agentName, integration.items);
 74→      try {
 75→        await ctx.editMessageText(
 76→          `<b>🔗 ${escapeHtml(agentName)} Integrations</b>\n\n${integration.items.map((i) => `• <b>${escapeHtml(i.name)}</b> — ${escapeHtml(i.description)}`).join("\n")}`,
 77→          { parse_mode: "HTML", reply_markup: keyboard },
 78→        );
 79→      } catch {
 80→        await ctx.reply(
 81→          `<b>🔗 ${escapeHtml(agentName)} Integrations</b>`,
 82→          { parse_mode: "HTML", reply_markup: keyboard },
 83→        );
 84→      }
 85→      return;
 86→    }
 87→
 88→    // Install / uninstall item
 89→    const actionMatch = data.match(/^i:(install|uninstall):([^:]+):(.+)$/);
 90→    if (!actionMatch) return;
 91→
 92→    const action = actionMatch[1] as "install" | "uninstall";
 93→    const agentName = actionMatch[2];
 94→    const itemId = actionMatch[3];
 95→
 96→    const { getIntegration } = await import("../../../cli/integrate.js");
 97→    const integration = getIntegration(agentName);
 98→    if (!integration) return;
 99→
100→    const item = integration.items.find((i) => i.id === itemId);
101→    if (!item) return;
102→
103→    const result = action === "install"
104→      ? await item.install()
105→      : await item.uninstall();
106→
107→    // Save state to config
108→    const installed = action === "install" && result.success;
109→    await core.configManager.save({
110→      integrations: {
111→        [agentName]: {
112→          installed,
113→          installedAt: installed ? new Date().toISOString() : undefined,
114→        },
115→      },
116→    });
117→
118→    const statusEmoji = result.success ? "✅" : "❌";
119→    const actionLabel = action === "install" ? "installed" : "uninstalled";
120→    const logsText = result.logs.map((l) => `<code>${escapeHtml(l)}</code>`).join("\n");
121→    const resultText = `${statusEmoji} <b>${escapeHtml(item.name)}</b> ${actionLabel}.\n\n${logsText}`;
122→
123→    const keyboard = buildAgentItemsKeyboard(agentName, integration.items);
124→    try {
125→      await ctx.editMessageText(
126→        `<b>🔗 ${escapeHtml(agentName)} Integrations</b>\n\n${resultText}`,
127→        { parse_mode: "HTML", reply_markup: keyboard },
128→      );
129→    } catch {
130→      await ctx.reply(resultText, { parse_mode: "HTML" });
131→    }
132→  });
133→}
