 62→          `<b>Queue:</b> ${session.queueDepth} pending`,
 63→        { parse_mode: "HTML" },
 64→      );
 65→    } else {
 66→      // Fallback: show stored session info when not loaded in memory (e.g. after restart)
 67→      const record = core.sessionManager.getRecordByThread("telegram", String(threadId));
 68→      if (record) {
 69→        await ctx.reply(
