  1→import type { Bot, Context } from "grammy";
  2→import { InlineKeyboard } from "grammy";
  3→import type { OpenACPCore } from "../../../core/index.js";
  4→import { getSafeFields, resolveOptions, getConfigValue, isHotReloadable, type ConfigFieldDef } from "../../../core/config-registry.js";
  5→import { createChildLogger } from "../../../core/log.js";
