  9→function buildSettingsKeyboard(core: OpenACPCore): InlineKeyboard {
 10→  const config = core.configManager.get();
 11→  const fields = getSafeFields();
 12→  const kb = new InlineKeyboard();
 13→
 14→  for (const field of fields) {
 15→    const value = getConfigValue(config, field.path);
 16→    const label = formatFieldLabel(field, value);
 17→
 18→    if (field.type === 'toggle') {
 19→      kb.text(`${label}`, `s:toggle:${field.path}`).row();
 20→    } else if (field.type === 'select') {
 21→      kb.text(`${label}`, `s:select:${field.path}`).row();
 22→    } else {
 23→      kb.text(`${label}`, `s:input:${field.path}`).row();
 24→    }
 25→  }
 26→
 27→  kb.text("◀️ Back to Menu", "s:back");
 28→  return kb;
 29→}
 30→
 31→function formatFieldLabel(field: ConfigFieldDef, value: unknown): string {
 32→  const icons: Record<string, string> = {
 33→    agent: '🤖', logging: '📝', tunnel: '🔗',
 34→    security: '🔒', workspace: '📁', storage: '💾',
 35→  };
 36→  const icon = icons[field.group] ?? '⚙️';
 37→
 38→  if (field.type === 'toggle') {
 39→    return `${icon} ${field.displayName}: ${value ? 'ON' : 'OFF'}`;
 40→  }
 41→  return `${icon} ${field.displayName}: ${String(value)}`;
 42→}
