 44→export async function handleSettings(ctx: Context, core: OpenACPCore): Promise<void> {
 45→  const kb = buildSettingsKeyboard(core);
 46→  await ctx.reply(`<b>⚙️ Settings</b>\nTap to change:`, {
 47→    parse_mode: "HTML",
 48→    reply_markup: kb,
 49→  });
 50→}
 51→
 52→export function setupSettingsCallbacks(
 53→  bot: Bot,
 54→  core: OpenACPCore,
 55→  getAssistantSession: () => { topicId: number; enqueuePrompt: (p: string) => Promise<void> } | undefined,
 56→): void {
 57→  bot.callbackQuery(/^s:toggle:/, async (ctx) => {
 58→    const fieldPath = ctx.callbackQuery.data.replace('s:toggle:', '');
 59→    const config = core.configManager.get();
 60→    const currentValue = getConfigValue(config, fieldPath);
 61→    const newValue = !currentValue;
 62→
 63→    try {
 64→      const updates = buildNestedUpdate(fieldPath, newValue);
 65→      await core.configManager.save(updates, fieldPath);
 66→
 67→      const toast = isHotReloadable(fieldPath)
 68→        ? `✅ ${fieldPath} = ${newValue}`
 69→        : `✅ ${fieldPath} = ${newValue} (restart needed)`;
 70→      try { await ctx.answerCallbackQuery({ text: toast }); } catch { /* expired */ }
 71→
 72→      try {
 73→        await ctx.editMessageReplyMarkup({ reply_markup: buildSettingsKeyboard(core) });
 74→      } catch { /* ignore */ }
 75→    } catch (err) {
 76→      log.error({ err, fieldPath }, 'Failed to toggle config');
 77→      try { await ctx.answerCallbackQuery({ text: '❌ Failed to update' }); } catch { /* expired */ }
 78→    }
 79→  });
 80→
 81→  bot.callbackQuery(/^s:select:/, async (ctx) => {
 82→    const fieldPath = ctx.callbackQuery.data.replace('s:select:', '');
 83→    const config = core.configManager.get();
 84→    const fieldDef = getSafeFields().find(f => f.path === fieldPath);
 85→    if (!fieldDef) return;
 86→
 87→    const options = resolveOptions(fieldDef, config) ?? [];
 88→    const currentValue = getConfigValue(config, fieldPath);
 89→    const kb = new InlineKeyboard();
 90→
 91→    for (const opt of options) {
 92→      const marker = opt === String(currentValue) ? ' ✓' : '';
 93→      kb.text(`${opt}${marker}`, `s:pick:${fieldPath}:${opt}`).row();
 94→    }
 95→    kb.text("◀️ Back", "s:back:refresh");
 96→
 97→    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
 98→
 99→    try {
100→      await ctx.editMessageText(`<b>⚙️ ${fieldDef.displayName}</b>\nSelect a value:`, {
101→        parse_mode: "HTML",
102→        reply_markup: kb,
103→      });
104→    } catch { /* ignore */ }
105→  });
106→
107→  bot.callbackQuery(/^s:pick:/, async (ctx) => {
108→    const parts = ctx.callbackQuery.data.replace('s:pick:', '').split(':');
109→    const fieldPath = parts.slice(0, -1).join(':');
110→    const newValue = parts[parts.length - 1];
111→
112→    try {
113→      const updates = buildNestedUpdate(fieldPath, newValue);
114→      await core.configManager.save(updates, fieldPath);
115→
116→      try { await ctx.answerCallbackQuery({ text: `✅ ${fieldPath} = ${newValue}` }); } catch { /* expired */ }
117→      try {
118→        await ctx.editMessageText(`<b>⚙️ Settings</b>\nTap to change:`, {
119→          parse_mode: "HTML",
120→          reply_markup: buildSettingsKeyboard(core),
121→        });
122→      } catch { /* ignore */ }
123→    } catch (err) {
124→      log.error({ err, fieldPath }, 'Failed to set config');
125→      try { await ctx.answerCallbackQuery({ text: '❌ Failed to update' }); } catch { /* expired */ }
126→    }
127→  });
128→
129→  bot.callbackQuery(/^s:input:/, async (ctx) => {
130→    const fieldPath = ctx.callbackQuery.data.replace('s:input:', '');
131→    const config = core.configManager.get();
132→    const fieldDef = getSafeFields().find(f => f.path === fieldPath);
133→    if (!fieldDef) return;
134→
135→    const currentValue = getConfigValue(config, fieldPath);
136→    const assistant = getAssistantSession();
137→
138→    if (!assistant) {
139→      try { await ctx.answerCallbackQuery({ text: '⚠️ Start the assistant first (/assistant)' }); } catch { /* expired */ }
140→      return;
141→    }
142→
143→    try { await ctx.answerCallbackQuery({ text: `Delegating to assistant...` }); } catch { /* expired */ }
144→
145→    const prompt = `User wants to change ${fieldDef.displayName} (config path: ${fieldPath}). Current value: ${JSON.stringify(currentValue)}. Ask them for the new value and apply it using: openacp config set ${fieldPath} <value>`;
146→    await assistant.enqueuePrompt(prompt);
147→  });
148→
149→  bot.callbackQuery("s:back", async (ctx) => {
150→    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
151→    const { buildMenuKeyboard } = await import('./menu.js');
152→    try {
153→      await ctx.editMessageText(`<b>OpenACP Menu</b>\nChoose an action:`, {
154→        parse_mode: "HTML",
155→        reply_markup: buildMenuKeyboard(),
156→      });
157→    } catch { /* ignore */ }
158→  });
159→
160→  bot.callbackQuery("s:back:refresh", async (ctx) => {
161→    try { await ctx.answerCallbackQuery(); } catch { /* expired */ }
162→    try {
163→      await ctx.editMessageText(`<b>⚙️ Settings</b>\nTap to change:`, {
164→        parse_mode: "HTML",
165→        reply_markup: buildSettingsKeyboard(core),
166→      });
167→    } catch { /* ignore */ }
168→  });
169→}
170→
171→function buildNestedUpdate(dotPath: string, value: unknown): Record<string, unknown> {
172→  const parts = dotPath.split('.');
173→  const result: Record<string, unknown> = {};
174→  let target = result;
175→  for (let i = 0; i < parts.length - 1; i++) {
176→    target[parts[i]] = {};
177→    target = target[parts[i]] as Record<string, unknown>;
178→  }
179→  target[parts[parts.length - 1]] = value;
180→  return result;
181→}
