625→      await configManager.writeNew(config);
626→    } catch (writeErr) {
627→      console.log(
628→        fail(`Could not save config: ${(writeErr as Error).message}`),
629→      );
630→      return false;
631→    }
632→
633→    console.log("");
634→    console.log(
635→      ok(`Config saved to ${c.bold}${configManager.getConfigPath()}`),
636→    );
637→
638→    // Pre-download cloudflared if tunnel enabled
639→    if (config.tunnel.enabled && config.tunnel.provider === "cloudflare") {
640→      console.log(dim("  Ensuring cloudflared is installed..."));
641→      try {
642→        const { ensureCloudflared } = await import(
643→          "../tunnel/providers/install-cloudflared.js"
644→        );
645→        const binPath = await ensureCloudflared();
646→        console.log(ok(`cloudflared ready at ${dim(binPath)}`));
647→      } catch (err) {
648→        console.log(
649→          warn(
650→            `Could not install cloudflared: ${(err as Error).message}. Tunnel may not work.`,
651→          ),
652→        );
653→      }
654→    }
655→
656→    console.log(ok("Starting OpenACP..."));
657→    console.log("");
658→
659→    return true;
660→  } catch (err) {
661→    if ((err as Error).name === "ExitPromptError") {
662→      console.log(dim("\nSetup cancelled."));
663→      return false;
664→    }
665→    throw err;
666→  }
