    .addComponents(
      new ButtonBuilder()
        .setCustomId(`d:${sessionId}`)
        .setLabel(isDangerous ? '🔓 Disable Dangerous Mode' : '⚠️ Enable Dangerous Mode')
        .setStyle(isDangerous ? ButtonStyle.Success : ButtonStyle.Danger)
    )
