): Promise<void> {
  try {
    const thread = guild.channels.cache.get(threadId) as ThreadChannel | undefined
      ?? await guild.channels.fetch(threadId) as ThreadChannel | null
    if (thread) {
      await thread.delete('OpenACP session cleanup')
