  workspace?: string
}

const ACTION_TTL = 5 * 60 * 1000 // 5 minutes
const actions = new Map<string, { action: DetectedAction; expiresAt: number }>()

export function detectAction(text: string): DetectedAction | null {
  // /new [agent] [workspace]
  const newMatch = text.match(/\/new(?:\s+(\S+))?(?:\s+(\S+))?/)
  if (newMatch) {
    return { type: 'new_session', agent: newMatch[1], workspace: newMatch[2] }
  }

  // /cancel
  if (/\/cancel\b/.test(text)) {
    return { type: 'cancel_session' }
  }

  // Natural language
  if (/\b(?:create|start|new)\s+(?:a\s+)?session\b/i.test(text)) {
    return { type: 'new_session' }
  }
  if (/\b(?:cancel|stop|kill)\s+(?:the\s+)?session\b/i.test(text)) {
    return { type: 'cancel_session' }
  }

  return null
}

export function storeAction(action: DetectedAction): string {
  // Clean expired
  const now = Date.now()
  for (const [id, entry] of actions) {
    if (entry.expiresAt < now) actions.delete(id)
  }

  const id = nanoid(8)
  actions.set(id, { action, expiresAt: now + ACTION_TTL })
  return id
}

export function getAction(id: string): DetectedAction | null {
  const entry = actions.get(id)
  if (!entry || entry.expiresAt < Date.now()) {
    actions.delete(id)
    return null
  }
  return entry.action
}

export function removeAction(id: string): void {
  actions.delete(id)
}

export function buildActionKeyboard(actionId: string, action: DetectedAction): ActionRowBuilder<ButtonBuilder> | null {
  const row = new ActionRowBuilder<ButtonBuilder>()

  if (action.type === 'new_session') {
    const label = action.agent ? `New Session (${action.agent})` : 'New Session'
    row.addComponents(
      new ButtonBuilder()
        .setCustomId(`a:${actionId}`)
        .setLabel(label)
        .setStyle(ButtonStyle.Primary),
      new ButtonBuilder()
        .setCustomId(`a:dismiss:${actionId}`)
        .setLabel('Dismiss')
        .setStyle(ButtonStyle.Secondary),
    )
  } else if (action.type === 'cancel_session') {
    row.addComponents(
      new ButtonBuilder()
        .setCustomId(`a:${actionId}`)
        .setLabel('Cancel Session')
        .setStyle(ButtonStyle.Danger),
      new ButtonBuilder()
        .setCustomId(`a:dismiss:${actionId}`)
        .setLabel('Dismiss')
        .setStyle(ButtonStyle.Secondary),
    )
  } else {
    return null
  }

  return row
}
