      ? `[View](https://discord.com/channels/${adapter.getGuildId()}/${s.threadId})`
      : ''
    return `• **${s.name ?? s.id}** (${s.agentName}) — ${s.status} ${link}`
  })

  const row = new ActionRowBuilder<ButtonBuilder>()
    .addComponents(
      new ButtonBuilder()
        .setCustomId('m:cleanup:all')
